/* OpenMind — offline shell for the static build.
 *
 * The static build has no server, so "offline" needs no sync protocol: the
 * learner's work is already on the device. What it does need is the app itself,
 * and that is what this caches — the shell, the stylesheet and the engine
 * bundle. Bump CACHE when the bundle changes; the engine file is generated by
 * scripts/build-static-app.mjs and its name does not carry a version.
 */
const CACHE = "openmind-static-v3";
const SHELL = ["./", "index.html", "app.css", "app.js", "openmind.engine.js"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // never touch another origin's traffic
  event.respondWith(
    caches.match(req).then((hit) => {
      const network = fetch(req)
        .then((res) => {
          if (res && res.ok) caches.open(CACHE).then((c) => c.put(req, res.clone()));
          return res;
        })
        .catch(() => hit);
      return hit || network;
    }),
  );
});
